// Only remove images generated by this endpoint for this user in our cloud.
export function ownedPublicId(
  url: string | undefined,
  cloud: string,
  userId: string,
) {
  if (!url) return undefined;
  try {
    const parsed = new URL(url);
    const prefix = `/${cloud}/image/upload/`;
    if (
      parsed.protocol !== "https:" ||
      parsed.hostname !== "res.cloudinary.com" ||
      !parsed.pathname.startsWith(prefix)
    )
      return undefined;
    const path = parsed.pathname.slice(prefix.length);
    const match = path.match(
      /^v\d+\/(docvia\/avatars\/([a-f\d]{24})\/[a-f\d-]{36})\.jpg$/i,
    );
    return match?.[2] === userId ? match[1] : undefined;
  } catch {
    return undefined;
  }
}
